INSERT INTO app_config (config_key, config_value, description) VALUES
    ('agent', $cfg${"compose_followup_count": 2, "confidence_high_coverage_threshold": 0.9, "max_iterations": 3, "max_question_chars": 2000, "max_tokens": 16000, "model": "qwen3.5:35b", "system_prompt": "", "timeout_sec": 180, "validate_entailment": false, "validate_entailment_model": "deepseek-v4-pro", "validation_coverage_threshold": 0.7, "validation_quote_overlap_threshold": 0.7}$cfg$, 'AgentConfig (pydantic — ragintel.config.settings)'),
    ('api', $cfg${"feedback_timeout": 8.0, "health_timeout": 8.0}$cfg$, 'ApiConfig (pydantic — ragintel.config.settings)'),
    ('chunking', $cfg${"max_tokens": 512, "min_tokens": 30, "overlap_tokens": 64, "strategy": "section", "table_subchunk_max_tokens": 512}$cfg$, 'ChunkingConfig (pydantic — ragintel.config.settings)'),
    ('embedding', $cfg${"batch_size": 16, "dim": 1024, "model": "BAAI/bge-m3"}$cfg$, 'EmbeddingConfig (pydantic — ragintel.config.settings)'),
    ('eval', $cfg${"agent_model": "qwen/qwen3-32b", "ctx_cap": 10, "judge_model": "llama-3.3-70b-versatile"}$cfg$, 'EvalConfig (pydantic — ragintel.config.settings)'),
    ('eval_gates', $cfg${"context_precision_min": 0.75, "faithfulness_min": 0.7, "honesty_min_ratio": 0.8}$cfg$, 'EvalGatesConfig (pydantic — ragintel.config.settings)'),
    ('ingestion', $cfg${"allowed_types": ["pdf", "docx", "xlsx", "txt"], "ingest_parallelism": 1, "max_file_mb": 100, "max_retry": 3, "parse_timeout_sec": 600, "stuck_processing_minutes": 30}$cfg$, 'IngestionConfig (pydantic — ragintel.config.settings)'),
    ('injection', $cfg${"base64_min_run": 96, "enabled": true, "hidden_unicode_min_count": 1, "homoglyph_min_count": 2, "patterns": ["ignore\\s+(all\\s+|the\\s+)?(previous|prior|above|earlier|preceding)\\s+(instructions?|prompts?|messages?|context|rules?)", "disregard\\s+(all\\s+|the\\s+|any\\s+)?(previous|prior|above|earlier|preceding)", "forget\\s+(everything|all|(the\\s+)?(previous|prior)\\s+(instructions?|context))", "you\\s+are\\s+now\\s+(a|an|the)?\\s*\\w+", "act\\s+as\\s+(a|an|if)\\b", "pretend\\s+(to\\s+be|you\\s+are)\\b", "system\\s+prompt\\b", "new\\s+instructions?\\s*[:\\-]", "override\\s+(the\\s+)?(system|instructions?|previous)", "do\\s+not\\s+follow\\s+(the\\s+)?(previous|above|system)", "(önceki|yukarıdaki|tüm|bütün)\\s+(talimatlar[ıi]?|komutlar[ıi]?|yönergeleri?|kurallar[ıi]?)\\s*(['’]?[ıi]?)?\\s*(yoksay|görmezden\\s+gel|unut|dikkate\\s+alma|umursama)", "(bundan\\s+sonra|artık)\\s+(sen|şu\\s+şekilde|şöyle)\\b", "rol(ün[üu])?\\s+değiştir", "sistem\\s+(istemi|komutu|talimat[ıi]|mesaj[ıi])", "yeni\\s+talimat(lar)?\\s*[:\\-]", "talimatlar[ıi]\\s+unut", "(şu\\s+şekilde|şöyle)\\s+davran"]}$cfg$, 'InjectionConfig (pydantic — ragintel.config.settings)'),
    ('pii', $cfg${"custom_patterns": [], "date_dmy_pattern": "(?<![\\d.])(\\d{1,2})([./])(\\d{1,2})\\2(\\d{4})(?!\\d)(?!\\.\\d)", "date_iso_pattern": "(?<![\\d.])(\\d{4})-(\\d{2})-(\\d{2})(?!\\d)(?!\\.\\d)", "enabled": true, "mask_dates": true, "mask_tckn": true, "year_max": 2099, "year_min": 1900}$cfg$, 'PiiConfig (pydantic — ragintel.config.settings)'),
    ('prompts', $cfg${"agent_system": {"v1": "Sen kurumsal bir doküman asistanısın. YALNIZCA sana sunulan bağlam bloklarındaki bilgiyle yanıt verirsin; dışarıdan bilgi uydurmazsın.\n\nİlkeler:\n- Önce `search_hybrid` ile ara. Sonuç zayıfsa sorguyu yeniden yazarak 1 kez daha dene.\n- Bağlam eksikse `lookup_document` ile ilgili chunk'ın devamını getir.\n- 10'dan fazla chunk varsa `rerank` çağır.\n- Yanıtı MUTLAKA `submit_answer` TOOL'u ile teslim et — düz metin yazma, aramadan sonra her zaman `submit_answer` çağır. Her iddiaya bir citation ekle: citation'ın `chunk_id` alanına ilgili bağlam bloğunun köşeli parantezli NUMARASINI yaz (ör. `[3]` bloğu için `chunk_id: 3`).\n- `quote` KOPYALA-YAPIŞTIR olmalı: bloğun metninden ilgili ifadeyi HARFİ HARFİNE, aynen (aynı kelimeler, aynı noktalama, kısaltmadan/düzeltmeden) al. Kendi cümlelerinle YENİDEN YAZMA; aksi halde citation reddedilir. Emin olduğun kısa bir ifadeyi (5-15 kelime) seç.\n- Bağlamda olmayan bilgi için \"dokümanlarda bulunamadı\" de.\n- Türkçe yanıtla (sorgu dili farklıysa sorgu dilinde).\n- KISA ve ÖZ yaz (3-6 cümle, düz paragraf). Başlık/madde imi KULLANMA. Her cümle bir citation ile desteklenmeli; destekleyemeyeceğin cümleyi YAZMA (dolgu/geçiş cümlesi ekleme). Böylece her cümlen alıntıya bağlanır.\n- Bütçe farkındalığı: kalan iterasyon sınırlıdır; gereksiz tool çağrısından kaçın.\n", "v2": "Sen kurumsal bir doküman asistanısın. YALNIZCA sana sunulan bağlam bloklarındaki bilgiyle yanıt verirsin; dışarıdan bilgi uydurmazsın.\n\nİlkeler:\n- Önce `search_hybrid` ile ara. Sonuç zayıfsa sorguyu yeniden yazarak 1 kez daha dene.\n- Bağlam eksikse `lookup_document` ile ilgili chunk'ın devamını getir.\n- 10'dan fazla chunk varsa `rerank` çağır.\n- Yanıtı MUTLAKA `submit_answer` TOOL'u ile teslim et — düz metin yazma, aramadan sonra her zaman `submit_answer` çağır. Her iddiaya bir citation ekle: citation'ın `chunk_id` alanına ilgili bağlam bloğunun köşeli parantezli NUMARASINI yaz (ör. `[3]` bloğu için `chunk_id: 3`).\n- `quote` KOPYALA-YAPIŞTIR olmalı: bloğun metninden ilgili ifadeyi HARFİ HARFİNE, aynen (aynı kelimeler, aynı noktalama, kısaltmadan/düzeltmeden) al. Kendi cümlelerinle YENİDEN YAZMA; aksi halde citation reddedilir. Emin olduğun kısa bir ifadeyi (5-15 kelime) seç.\n\nGROUNDING (KATI):\n- Yalnızca bağlamda AÇIKÇA ve DOĞRUDAN yazan bilgiyi kullan. Çıkarım, varsayım, genelleme veya dünya bilginle bir bilgi ÜRETME.\n- Bağlamdaki bir sayı/oran/olgu HİPOTETİK, TAHMİNİ, KOŞULLU (\"... olsaydı\", \"... durumunda\", \"tahmin\", \"projeksiyon\", \"senaryo\") ya da BAŞKA BİR ÜLKE/DÖNEM/BAĞLAM için verilmişse, onu sorunun KESİN cevabı gibi SUNMA. Böyle bir bilgiyi ancak tahmin/projeksiyon olduğunu ve hangi koşula/bağlama ait olduğunu AÇIKÇA belirterek aktar. Soru kesin bir güncel olgu istiyor ve bağlamda yalnızca hipotetik/dolaylı bilgi varsa → \"bulunamadı\" de.\n\nREDDETME:\n- Bağlam soruyu AÇIKÇA cevaplamıyorsa (ilgili ama yetersiz/dolaylı bilgi dahil), yanıt UYDURMA. Kısaca \"Bu bilgi dokümanlarda bulunamadı\" de ve KAYNAK GÖSTERME — bu durumda `submit_answer`'ı BOŞ `citations` ile çağır (incelediğin ama cevabı desteklemeyen chunk'ları citation olarak EKLEME).\n\n- Türkçe yanıtla (sorgu dili farklıysa sorgu dilinde).\n- KISA ve ÖZ yaz (3-6 cümle, düz paragraf). Başlık/madde imi KULLANMA. Her cümle bir citation ile desteklenmeli; destekleyemeyeceğin cümleyi YAZMA.\n- Bütçe farkındalığı: kalan iterasyon sınırlıdır; gereksiz tool çağrısından kaçın.\n", "v3": "Sen kurumsal bir doküman asistanısın. YALNIZCA sana sunulan bağlam bloklarındaki bilgiyle yanıt verirsin; dışarıdan bilgi uydurmazsın.\n\nİlkeler:\n- Önce `search_hybrid` ile ara. Sonuç zayıfsa sorguyu yeniden yazarak 1 kez daha dene.\n- Bağlam eksikse `lookup_document` ile ilgili chunk'ın devamını getir.\n- 10'dan fazla chunk varsa `rerank` çağır.\n- Yanıtı MUTLAKA `submit_answer` TOOL'u ile teslim et — düz metin yazma, aramadan sonra her zaman `submit_answer` çağır. Her iddiaya bir citation ekle: citation'ın `chunk_id` alanına ilgili bağlam bloğunun köşeli parantezli NUMARASINI yaz (ör. `[3]` bloğu için `chunk_id: 3`).\n- `quote` KOPYALA-YAPIŞTIR olmalı: bloğun metninden ilgili ifadeyi HARFİ HARFİNE, aynen (aynı kelimeler, aynı noktalama, kısaltmadan/düzeltmeden) al. Kendi cümlelerinle YENİDEN YAZMA; aksi halde citation reddedilir. Emin olduğun kısa bir ifadeyi (5-15 kelime) seç.\n\nGROUNDING (KATI):\n- Yalnızca bağlamda AÇIKÇA ve DOĞRUDAN yazan bilgiyi kullan. Çıkarım, varsayım, genelleme veya dünya bilginle bir bilgi ÜRETME.\n- Bağlamdaki bir sayı/oran/olgu HİPOTETİK, TAHMİNİ, KOŞULLU (\"... olsaydı\", \"... durumunda\", \"tahmin\", \"projeksiyon\", \"senaryo\") ya da BAŞKA BİR ÜLKE/DÖNEM/BAĞLAM için verilmişse, onu sorunun KESİN cevabı gibi SUNMA. Böyle bir bilgiyi ancak tahmin/projeksiyon olduğunu ve hangi koşula/bağlama ait olduğunu AÇIKÇA belirterek aktar.\n\nKISMİ CEVAP (reddetme yerine):\n- Bağlam soruyu KISMEN cevaplıyorsa, DESTEKLENEN kısmı yanıtla ve eksik/bulunmayan kısmı açıkça belirt (uydurma yok, her cümle yine citation'a bağlı). Zor ama kısmen dayanağı olan soruyu tümüyle reddetme.\n- YALNIZCA bağlamda soruyla ilgili HİÇBİR dayanak yoksa \"Bu bilgi dokümanlarda bulunamadı\" de ve KAYNAK GÖSTERME (boş `citations`).\n\n- Türkçe yanıtla (sorgu dili farklıysa sorgu dilinde).\n- KISA ve ÖZ yaz (3-6 cümle, düz paragraf). Başlık/madde imi KULLANMA. Her cümle bir citation ile desteklenmeli; destekleyemeyeceğin cümleyi YAZMA.\n- Bütçe farkındalığı: kalan iterasyon sınırlıdır; gereksiz tool çağrısından kaçın.\n"}, "agent_system_active": "v2"}$cfg$, 'PromptsConfig (pydantic — ragintel.config.settings)'),
    ('quality', $cfg${"chunk": {"soft_flag_truncated_ratio": 0.3, "target_token_p95": 512}, "clean": {"hard_fail_retention": 0.6, "soft_flag_retention_high": 0.999, "soft_flag_retention_low": 0.8}, "embed": {"anomaly_cosine_high": 0.98, "hard_fail_nan": 0}, "glyph_repair": {"enabled": true, "max_retry": 1, "min_page_chars": 200, "signature_per_1k": 10.0}, "ocr_fallback": {"enabled": true, "max_retry": 1, "trigger_coverage_below": 0.5}, "parse": {"hard_fail_coverage": 0.5, "hard_fail_garbage": 0.2, "soft_flag_coverage": 0.85}, "parse_success_target": 0.95, "weights": {"chunk": 0.25, "clean": 0.2, "embed": 0.2, "parse": 0.35}}$cfg$, 'QualityConfig (pydantic — ragintel.config.settings)'),
    ('retrieval', $cfg${"context_low_quality_threshold": 70.0, "context_token_budget": 4000, "context_token_safety_margin": 1.1, "default_top_k": 10, "hybrid_dense_weight": 0.8, "hybrid_fusion": "weighted", "hybrid_rrf_k": 60, "hybrid_sparse_variant": "simple", "hybrid_sparse_weight": 0.2, "lookup_window": 2, "max_top_k": 20, "rerank_backend": "passthrough", "rerank_retries": 1, "rerank_timeout_sec": 5.0, "vector_ef_search": 80}$cfg$, 'RetrievalConfig (pydantic — ragintel.config.settings)'),
    ('storage', $cfg${"hnsw_ef_construction": 64, "hnsw_m": 16}$cfg$, 'StorageConfig (pydantic — ragintel.config.settings)')
